// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type CareerGrowthChartProps = Record<string, any>;

const CareerGrowthChart: React.FC<CareerGrowthChartProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 8,
  lineColor = "#34C759",
  textColor = "#FFFFFF",
  gridColor = "#333333",
  finalNumber = 40000,
  numberSuffix = "+",
  counterLabel = "Clients Served",
  timelineLabel = "Years in the Mortgage Industry",
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height);

  // Layout calculations
  const chartW = width * 0.8;
  const chartH = height * 0.55;
  const startX = width * 0.1;
  const startY = height * 0.75;
  const hLines = 5;
  const vLines = 8;

  // Normalized strictly increasing dataset with minor market-style fluctuations
  const normalizedData = [
    0.02, 0.03, 0.05, 0.04, 0.08, 0.12, 0.10, 0.15, 0.19, 0.18,
    0.22, 0.28, 0.35, 0.32, 0.39, 0.45, 0.51, 0.48, 0.55, 0.62,
    0.70, 0.68, 0.75, 0.82, 0.88, 0.85, 0.92, 0.97, 0.99, 1.00
  ];

  // Generate SVG path for the line graph
  const pathData = React.useMemo(() => {
    return normalizedData.map((val, i) => {
      const x = startX + (i / (normalizedData.length - 1)) * chartW;
      const y = startY - val * chartH;
      return `${i === 0 ? "M" : "L"} ${x} ${y}`;
    }).join(" ");
  }, [startX, startY, chartW, chartH]);

  const fillPathData = `${pathData} L ${startX + chartW} ${startY} L ${startX} ${startY} Z`;

  // Timing logic
  const gridFadeInStart = 0;
  const gridFadeInEnd = fps * 1;
  
  const lineStart = fps * 1;
  const lineDuration = (durationInSeconds * fps) - (fps * 2); 
  const lineEnd = lineStart + lineDuration;
  
  const countStart = lineStart + Math.floor(fps * 0.5);

  // Animations
  const gridOpacity = interpolate(frame, [gridFadeInStart, gridFadeInEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.ease)
  });

  const lineProgress = interpolate(frame, [lineStart, lineEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic)
  });

  const currentCount = interpolate(frame, [countStart, lineEnd], [0, finalNumber], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic)
  });

  const counterScale = spring({
    frame: frame - countStart,
    fps,
    config: { damping: 14, stiffness: 80 }
  });

  const counterOpacity = interpolate(frame, [countStart, countStart + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp"
  });

  // Calculate coordinates for the glowing leading dot
  const exactIndex = lineProgress * (normalizedData.length - 1);
  const lowerIndex = Math.floor(exactIndex);
  const upperIndex = Math.ceil(exactIndex);
  const fraction = exactIndex - lowerIndex;
  
  const lowerVal = normalizedData[lowerIndex] || 0;
  const upperVal = normalizedData[upperIndex] || 0;
  const currentVal = lowerVal + (upperVal - lowerVal) * fraction;
  
  const dotX = startX + chartW * lineProgress;
  const dotY = startY - currentVal * chartH;

  // Render variables
  const bgColor = transparentBackground ? undefined : backgroundColor;
  const isLanded = frame >= lineEnd;
  const displaySuffix = isLanded ? numberSuffix : "";

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", transition: "none", overflow: "hidden" }}>
      
      {/* Background SVG Layer for Grid & Graph */}
      <svg style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", transition: "none" }}>
        <defs>
          <linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={lineColor} stopOpacity={0.4} />
            <stop offset="100%" stopColor={lineColor} stopOpacity={0} />
          </linearGradient>
          <clipPath id="reveal-clip">
            <rect x={startX - 10} y={0} width={(chartW * lineProgress) + 10} height={height} />
          </clipPath>
        </defs>

        <g style={{ opacity: gridOpacity, transition: "none" }}>
          {/* Horizontal Grid Lines */}
          {Array.from({ length: hLines }).map((_, i) => {
            const y = startY - i * (chartH / (hLines - 1));
            return (
              <line
                key={`h-${i}`}
                x1={startX}
                y1={y}
                x2={startX + chartW}
                y2={y}
                stroke={gridColor}
                strokeWidth={width * 0.001}
                opacity={0.5}
                style={{ transition: "none" }}
              />
            );
          })}
          
          {/* Vertical Grid Lines */}
          {Array.from({ length: vLines }).map((_, i) => {
            const x = startX + i * (chartW / (vLines - 1));
            return (
              <line
                key={`v-${i}`}
                x1={x}
                y1={startY}
                x2={x}
                y2={startY - chartH}
                stroke={gridColor}
                strokeWidth={width * 0.001}
                strokeDasharray="10 10"
                opacity={0.3}
                style={{ transition: "none" }}
              />
            );
          })}
        </g>

        {/* Animated Line Graph Layer */}
        <g clipPath="url(#reveal-clip)" style={{ transition: "none" }}>
          <path d={fillPathData} fill="url(#areaGradient)" style={{ transition: "none" }} />
          <path 
            d={pathData} 
            fill="none" 
            stroke={lineColor} 
            strokeWidth={width * 0.003} 
            strokeLinejoin="round" 
            strokeLinecap="round"
            style={{ transition: "none" }} 
          />
        </g>

        {/* Leading Dot */}
        {lineProgress > 0 && lineProgress < 1 && (
          <g style={{ transition: "none" }}>
            <circle cx={dotX} cy={dotY} r={width * 0.015} fill={lineColor} opacity={0.2} style={{ transition: "none" }} />
            <circle cx={dotX} cy={dotY} r={width * 0.005} fill={lineColor} style={{ transition: "none" }} />
          </g>
        )}
      </svg>

      {/* Timeline Label */}
      <div style={{
        position: "absolute",
        bottom: height * 0.12,
        width: "100%",
        textAlign: "center",
        color: gridColor,
        fontSize: width * 0.012,
        letterSpacing: "0.25em",
        textTransform: "uppercase",
        opacity: gridOpacity,
        transition: "none",
        fontWeight: 600
      }}>
        {timelineLabel}
      </div>

      {/* Center Counter Overlay */}
      <AbsoluteFill style={{
        justifyContent: "center",
        alignItems: "center",
        pointerEvents: "none",
        transition: "none"
      }}>
        <div style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transform: `scale(${counterScale}) translateY(-${height * 0.05}px)`,
          opacity: counterOpacity,
          textShadow: `0px 10px 40px rgba(0,0,0,0.8), 0px 4px 10px rgba(0,0,0,0.5)`,
          transition: "none"
        }}>
          <div style={{
            fontSize: s * 0.25,
            fontWeight: 700,
            color: textColor,
            lineHeight: 1,
            fontVariantNumeric: "tabular-nums",
            letterSpacing: "-0.02em",
            transition: "none"
          }}>
            {Math.floor(currentCount).toLocaleString()}{displaySuffix}
          </div>
          <div style={{
            fontSize: s * 0.04,
            fontWeight: 600,
            color: textColor,
            opacity: 0.8,
            marginTop: height * 0.02,
            textTransform: "uppercase",
            letterSpacing: "0.15em",
            transition: "none"
          }}>
            {counterLabel}
          </div>
        </div>
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default CareerGrowthChart;